<?php
namespace App\Http\Controllers\Auth;
use App\Http\Controllers\Controller; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\RateLimiter; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
class AdminLoginController extends Controller {
 public function create(){return view('auth.admin-login');}
 public function store(Request $request){$data=$request->validate(['email'=>'required|email','password'=>'required|string']);$key=Str::lower($data['email']).'|'.$request->ip(); if(RateLimiter::tooManyAttempts($key,5)) throw ValidationException::withMessages(['email'=>'Too many sign-in attempts. Try again in '.RateLimiter::availableIn($key).' seconds.']); if(!Auth::attempt(['email'=>$data['email'],'password'=>$data['password'],'is_active'=>true],$request->boolean('remember'))){RateLimiter::hit($key,60);throw ValidationException::withMessages(['email'=>'The supplied credentials are invalid or the account is inactive.']);} $request->session()->regenerate(); RateLimiter::clear($key); $user=$request->user(); if(!in_array($user->role,['admin','editor'],true)){Auth::logout();$request->session()->invalidate();$request->session()->regenerateToken();throw ValidationException::withMessages(['email'=>'This account does not have administrator access.']);} $user->forceFill(['last_login_at'=>now()])->save(); return redirect()->intended(route('admin.dashboard')); }
 public function destroy(Request $request){Auth::logout();$request->session()->invalidate();$request->session()->regenerateToken();return redirect()->route('login')->with('status','You have been signed out.');}
}
